&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight typescript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// trpc/server.ts&lt;/span&gt;
&lt;span class="c1"&gt;// Server-side tRPC client for React Server Components&lt;/span&gt;
